const products=[{id:1,name:'にんじん',farmer:'○○農園',category:'野菜',unit:'1袋',price:180,stock:24,img:'carrot',place:'01 旬の野菜',desc:'毎日の料理に使いやすい、旬のにんじん。生産者の紹介とおすすめの食べ方を掲載する想定です。'},{id:2,name:'ミニトマト',farmer:'△△ファーム',category:'野菜',unit:'1パック',price:250,stock:8,img:'tomato',place:'01 旬の野菜',desc:'そのままおやつにも、サラダにも。商品ごとの量・生産者・産地を確認できます。'},{id:3,name:'季節のいちご',farmer:'○○農園',category:'果物',unit:'1パック',price:580,stock:3,img:'strawberry',place:'02 果物',desc:'季節の果物の表示サンプルです。本日の実際の入荷を表すものではありません。'},{id:4,name:'地元のお米',farmer:'□□ファーム',category:'米',unit:'2kg',price:1800,stock:10,img:'market',place:'03 お米・加工品',desc:'品種、内容量、産地、精米日などを掲載する想定です。写真は直売所のイメージです。'}];
let webFilter='all',appFilter='all',storyIndex=0;const favorites=new Set();
function switchView(id){document.querySelectorAll('.view').forEach(e=>e.classList.toggle('active',e.id===id));document.querySelectorAll('.tabs button').forEach(e=>e.classList.toggle('active',e.dataset.view===id));window.scrollTo(0,0);location.hash='view-'+id;}
document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>switchView(b.dataset.view));
function badge(p){return p.stock===0?'売り切れ':p.stock<=5?'残りわずか':'在庫あり'}
function renderProducts(){let q=document.getElementById('productSearch').value.trim();document.getElementById('webProducts').innerHTML=products.filter(p=>webFilter==='all'||p.category===webFilter).map(p=>`<button class="product" onclick="productDetail(${p.id})"><div class="productphoto"><img src="assets/${p.img}.jpg" alt="${p.name}のイメージ"><span class="stockbadge ${p.stock===0?'out':p.stock<=5?'low':''}">${badge(p)}</span></div><p class="farmer">${p.farmer} / サンプル</p><h3>${p.name}</h3><p class="price">¥${p.price.toLocaleString()}<small>${p.unit} / 税込</small></p></button>`).join('')||'<p class="empty">このカテゴリの入荷はありません。</p>';let list=products.filter(p=>(appFilter==='all'||appFilter==='favorites'&&favorites.has(p.id)||p.category===appFilter)&&(!q||(p.name+p.farmer).includes(q)));document.getElementById('appProducts').innerHTML=list.map(p=>`<article class="appproduct"><button class="thumb" onclick="productDetail(${p.id})"><img src="assets/${p.img}.jpg" alt="${p.name}のイメージ"></button><div class="info" role="button" tabindex="0" onclick="productDetail(${p.id})" onkeydown="if(event.key==='Enter')productDetail(${p.id})"><p class="farmer">${p.farmer}</p><h3>${p.name}</h3><p class="price">¥${p.price.toLocaleString()}<small>${p.unit} / 税込</small></p><p class="stock">${badge(p)} · 残り${p.stock}点</p></div><button class="fav ${favorites.has(p.id)?'saved':''}" onclick="toggleFav(${p.id})" aria-label="${p.name}をお気に入り${favorites.has(p.id)?'から解除':'に追加'}">${favorites.has(p.id)?'♥':'♡'}</button></article>`).join('')||'<p class="empty">該当する商品はありません。♡からお気に入りを追加できます。</p>';document.getElementById('heroCount').textContent=products.filter(p=>p.stock>0).length+'品目';document.querySelectorAll('#appFilters button').forEach(b=>b.classList.toggle('selected',b.dataset.filter===appFilter));document.querySelectorAll('.bottomnav button').forEach((b,i)=>b.classList.toggle('selected',i===(appFilter==='favorites'?1:0)));}
function toggleFav(id){favorites.has(id)?favorites.delete(id):favorites.add(id);renderProducts()}
function showDetail(title,body){const d=document.getElementById('detailContent');d.replaceChildren();const h=document.createElement('h2'),p=document.createElement('p');h.textContent=title;p.textContent=body;d.append(h,p);document.getElementById('detail').showModal()}
function productDetail(id){const p=products.find(p=>p.id===id);document.getElementById('detailContent').innerHTML=`<img class="detailimg" src="assets/${p.img}.jpg" alt="${p.name}のイメージ"><span class="tag">商品詳細のモック</span><h2>${p.name}</h2><p>${p.farmer} / 生産者名はサンプル</p><p class="price">¥${p.price.toLocaleString()} <small>${p.unit} / 税込</small></p><p>${p.desc}</p><div class="detailmeta"><p>在庫目安：${badge(p)}（残り${p.stock}点）<br>売り場：${p.place}<br>最新のデモ操作を反映 / 来店時の在庫は保証されません</p></div><button class="primary" onclick="document.getElementById('detail').close();switchView('web');document.getElementById('map').scrollIntoView()">売り場を確認する ↗</button>`;document.getElementById('detail').showModal()}
document.getElementById('detail').addEventListener('click',e=>{if(e.target.id==='detail')e.target.close()});
for(const scope of ['web','app'])document.querySelectorAll('#'+scope+'Filters button').forEach(b=>b.onclick=()=>{if(scope==='web')webFilter=b.dataset.filter;else appFilter=b.dataset.filter;document.querySelectorAll('#'+scope+'Filters button').forEach(x=>x.classList.toggle('selected',x===b));renderProducts()});document.getElementById('productSearch').oninput=renderProducts;
const pos=document.getElementById('posProduct');pos.innerHTML=products.map(p=>`<option value="${p.id}">${p.name} / ${p.unit}</option>`).join('');function loadPos(){const p=products.find(p=>p.id===+pos.value);document.getElementById('posPrice').value=p.price;document.getElementById('posStock').value=p.stock}pos.onchange=loadPos;
function updatePOS(sell){const p=products.find(p=>p.id===+pos.value);if(sell){if(!p.stock){document.getElementById('posFeedback').textContent='在庫が0のため販売できません。';return}p.stock--;}else{const price=+document.getElementById('posPrice').value,stock=+document.getElementById('posStock').value;if(!Number.isInteger(price)||!Number.isInteger(stock)||price<0||stock<0){document.getElementById('posFeedback').textContent='価格と在庫は0以上の整数を入力してください。';return}p.price=price;p.stock=stock}loadPos();renderProducts();document.getElementById('appTime').textContent='たった今';document.getElementById('posFeedback').textContent=`${p.name}：${sell?'1点販売しました。':'更新しました。'} 在庫 ${p.stock}点 / ¥${p.price.toLocaleString()}`;document.querySelector('.live').textContent='● デモ操作を反映（たった今）'}document.getElementById('posUpdate').onclick=()=>updatePOS(false);document.getElementById('posSell').onclick=()=>updatePOS(true);
const calendar=document.getElementById('calendar');calendar.innerHTML=['日','月','火','水','木','金','土'].map(x=>`<span class="weekday">${x}</span>`).join('')+'<span></span>'.repeat(4)+Array.from({length:31},(_,i)=>{let d=i+1;return `<button class="${[6,13,20,27].includes(d)?'restday':[17,24].includes(d)?'eventday':''}" onclick="pickDate(${d},this)">${d}</button>`}).join('');function pickDate(d,b){calendar.querySelectorAll('button').forEach(x=>x.classList.toggle('chosen',x===b));document.getElementById('caldetail').textContent=`10月${d}日：`+([6,13,20,27].includes(d)?'休業日（通常の火曜定休をもとにした表示例）':d===17?'秋の実りと、農家さんマルシェ 10:00–14:00（企画案）':d===24?'親子で楽しむ、旬の野菜教室 11:00–（企画案）':'9:00–17:00 営業予定（表示例）')}
function mapPick(title,desc){document.getElementById('maptitle').textContent=title;document.getElementById('mapdesc').textContent=desc+' 配置は提案用のサンプルです。'}
const posts=[['tomato','今日の入荷。'],['type','旬を、<br>いつもの食卓に。'],['strawberry','農家さんの果物が<br>今日のデザートに。'],['carrot','今夜は何を<br>つくろう？'],['cafe','お散歩のあとに、<br>ひと休み。'],['type','週末は、<br>ゆりいちへ。'],['market','地元の旬を<br>買いに。'],['strawberry','ひと粒の、<br>ごほうび。'],['tomato','おいしい、の<br>向こう側。']];document.getElementById('instagrid').innerHTML=posts.map((p,i)=>`<button class="post ${p[0]==='type'?'type':''}" onclick="showDetail('Instagram投稿の構成例','${p[1].replace(/<br>/g,'')} 写真と短い見出しで興味を引き、本文で生産者・商品・入荷日・価格などを紹介。今日の情報はストーリー、継続して見てほしい情報は投稿とハイライトに保存します。')">${p[0]==='type'?'<small>YURIICHI JOURNAL</small>':`<img src="assets/${p[0]}.jpg" alt="投稿イメージ">`}<span>${p[1]}</span></button>`).join('');
const stories=[{img:'market',kicker:'10.14 WED / OPEN',title:'本日も、<br>オープンしました。',body:'今日の旬が、届いています。',price:'9:00 – 17:00',link:'今日の入荷を見る',view:'app'},{img:'tomato',kicker:'TODAY’S ARRIVALS',title:'今日、<br>届きました。',body:'△△ファームのミニトマト',price:'1パック ¥250（税込）',link:'ほかの入荷もチェック',view:'app'},{img:'strawberry',kicker:'TODAY’S CAFE SPECIAL',title:'農家さんの旬を、<br>カフェでも。',body:'○○農園のいちごパフェ',price:'限定メニュー ¥680（税込）',link:'カフェのメニューを見る',view:'cafe'}];function setStory(i){storyIndex=i;const s=stories[i];document.getElementById('story').innerHTML=`<img src="assets/${s.img}.jpg" alt="ストーリーのイメージ"><div class="storyprogress">${stories.map((x,j)=>`<i class="${j===i?'on':''}"></i>`).join('')}</div><div class="storyaccount">ゆりいち · ストーリー配信例</div><div class="storytext"><p>${s.kicker}</p><h2>${s.title}</h2><strong>${s.body}</strong><span class="storyprice">${s.price}</span></div><button class="storybutton" onclick="${s.view==='cafe'?"switchView('web');document.getElementById('cafe').scrollIntoView()":"switchView('app')"}">${s.link} ↗</button><div class="storynote">商品・価格・農家名・日付はサンプルです。</div>`;}renderProducts();setStory(0);if(location.hash.startsWith('#view-')&&document.getElementById(location.hash.slice(6)))switchView(location.hash.slice(6));
